+    auto_txts = true;
+    if (mode == "cold") {
+      dut->rst_n=0; dut->rx_valid_i=0; dut->rx_sof_i=0; dut->rx_eof_i=0;
+      dut->rx_err_i=0; dut->rx_data_i=0; dut->rx_ts_i=0;
